<script module>  export const manifiesto = {    id: 'productos',    nombre: 'Productos',    icono: 'tag',    grupo: 'negocio',    orden: 3,    tablas: { productos: '++id, nombre, codigo, archivado', productoVariantes: '++id, productoId, nombre, codigo, archivado' },  };</script><script>  import { onMount } from 'svelte';  import { getDB, listar, guardar } from '../../core/db.js';  import { bus } from '../../core/bus.js';  import { avisar, confirmar } from '../../core/state.svelte.js';  import { n, m, fmt, fmtCant, fmtFH, genId, stockVariante, lotesDeVariante, valorLotesVariante, badgeStockVariante } from '../../core/util.js';  import { ProductoVarianteService } from '../../services/ProductoVarianteService.js';  import Icono from '../../core/Icono.svelte';  let productos = $state([]);  let variantes = $state([]);  let lotes = $state([]);  let busq = $state('');  let busqDebounced = $state('');  $effect(() => { const t = setTimeout(() => (busqDebounced = busq), 200); return () => clearTimeout(t); });  let mostrarArchivados = $state(false);  const expandido = $state({});  let pagina = $state(1);  const itemsPorPagina = 20;  let formProd = $state({ editId: '', nombre: '', codigo: '' });  let formVar = $state({ editId: '', productoId: '', nombre: '', codigo: '', unidad: '', precioBase: '', stockMin: '5', esCaja: false, unidadesPorCaja: '', varianteUnidadId: '', preciosEscalonados: [] });  let mostrarFormVariante = $state(false);  let prodSeleccionado = $state(null);  const filtrados = $derived((() => {    const p = mostrarArchivados ? productos : productos.filter((x) => !x.archivado);    const qry = busqDebounced.toLowerCase().trim();    if (!qry) return p;    return p.filter((x) => x.nombre.toLowerCase().includes(qry) || (x.codigo || '').toLowerCase().includes(qry));  })());  const totalPaginas = $derived(Math.max(1, Math.ceil(filtrados.length / itemsPorPagina)));  const filtradosPaginados = $derived(filtrados.slice((pagina - 1) * itemsPorPagina, pagina * itemsPorPagina));  async function recargar() {    [productos, variantes, lotes] = await Promise.all([listar('productos'), listar('productoVariantes'), listar('lotes')]);  }  onMount(() => { recargar(); const off = bus.on('recargar', recargar); return () => off(); });  function variantesDeProducto(pid) { return variantes.filter((v) => v.productoId === pid && !v.archivado); }  function variantesArchivadas(pid) { return variantes.filter((v) => v.productoId === pid && v.archivado); }  async function guardarProducto() {    const nombre = (formProd.nombre || '').trim();    if (!nombre) return avisar('Nombre obligatorio', 'bad');    const dup = productos.find((x) => x.nombre.toLowerCase() === nombre.toLowerCase() && x.id !== formProd.editId && !x.archivado);    if (dup) return avisar('Ya existe ese nombre', 'bad');    if (formProd.editId) {      const o = productos.find((x) => x.id === formProd.editId);      await guardar('productos', { ...o, nombre, codigo: (formProd.codigo || '').trim() });      avisar('Producto actualizado');    } else {      const prod = { id: genId('p'), nombre, codigo: (formProd.codigo || '').trim(), archivado: false };      await guardar('productos', prod);      await ProductoVarianteService.crear({ productoId: prod.id, nombre: prod.nombre, codigo: prod.codigo, unidad: 'u', precioBase: 0, stockMinimo: 5 });      avisar('Producto agregado con variante por defecto');    }    resetFormProd();    await recargar();    bus.emit('recargar');  }  function resetFormProd() { formProd = { editId: '', nombre: '', codigo: '' }; }  function editarProducto(p) { formProd = { editId: p.id, nombre: p.nombre, codigo: p.codigo || '' }; window.scrollTo(0, 0); }  async function archivarProducto(p) {    const vars = variantesDeProducto(p.id);    const hayStock = vars.some((v) => stockVariante(lotes, v.id) > 0);    if (hayStock) return avisar('No archivar: hay variantes con stock > 0', 'bad');    const ok = await confirmar('Archivar producto', 'Archivar ' + p.nombre + '? Se archivaran todas sus variantes.');    if (!ok) return;    await guardar('productos', { ...p, archivado: true });    for (const v of vars) { await ProductoVarianteService.actualizar(v, { archivado: true }); }    await recargar();    bus.emit('recargar');    avisar('Producto y variantes archivados');  }  async function restaurarProducto(p) {    await guardar('productos', { ...p, archivado: false });    const varsArch = variantesArchivadas(p.id);    for (const v of varsArch) { await ProductoVarianteService.actualizar(v, { archivado: false }); }    await recargar();    bus.emit('recargar');    avisar('Restaurado');  }  function abrirFormVariante(prod, varianteExistente) {    prodSeleccionado = prod;    mostrarFormVariante = true;    if (varianteExistente) {      formVar = { editId: varianteExistente.id, productoId: prod.id, nombre: varianteExistente.nombre, codigo: varianteExistente.codigo || '', unidad: varianteExistente.unidad || '', precioBase: String(varianteExistente.precioBase || ''), stockMin: String(varianteExistente.stockMinimo || 5), esCaja: !!varianteExistente.esCaja, unidadesPorCaja: String(varianteExistente.unidadesPorCaja || ''), varianteUnidadId: varianteExistente.varianteUnidadId || '', preciosEscalonados: clean(varianteExistente.preciosEscalonados || []) };    } else {      formVar = { editId: '', productoId: prod.id, nombre: '', codigo: '', unidad: '', precioBase: '', stockMin: '5', esCaja: false, unidadesPorCaja: '', varianteUnidadId: '', preciosEscalonados: [] };    }  }  function cerrarFormVariante() {    mostrarFormVariante = false;    prodSeleccionado = null;    formVar = { editId: '', productoId: '', nombre: '', codigo: '', unidad: '', precioBase: '', stockMin: '5', esCaja: false, unidadesPorCaja: '', varianteUnidadId: '', preciosEscalonados: [] };  }  function agregarEscalon() { formVar.preciosEscalonados = [...formVar.preciosEscalonados, { cantidadMinima: '', precioUnitario: '' }]; }  function quitarEscalon(i) { formVar.preciosEscalonados = formVar.preciosEscalonados.filter((_, idx) => idx !== i); }  async function guardarVariante() {    const nombre = (formVar.nombre || '').trim();    if (!nombre) return avisar('Nombre de variante obligatorio', 'bad');    const precio = n(formVar.precioBase);    if (precio <= 0) return avisar('Precio base debe ser > 0', 'bad');    const dup = variantes.find((v) => v.nombre.toLowerCase() === nombre.toLowerCase() && v.id !== formVar.editId && v.productoId === formVar.productoId && !v.archivado);    if (dup) return avisar('Ya existe esa variante', 'bad');    const datos = {      nombre, codigo: (formVar.codigo || '').trim(), unidad: (formVar.unidad || '').trim(), precioBase: precio,      stockMinimo: n(formVar.stockMin), esCaja: formVar.esCaja, unidadesPorCaja: n(formVar.unidadesPorCaja),      varianteUnidadId: formVar.varianteUnidadId || '',      preciosEscalonados: formVar.preciosEscalonados.map((pe) => ({ cantidadMinima: n(pe.cantidadMinima), precioUnitario: n(pe.precioUnitario) })),    };    try {      if (formVar.editId) {        const v = variantes.find((x) => x.id === formVar.editId);        await ProductoVarianteService.actualizar(v, datos);        avisar('Variante actualizada');      } else {        await ProductoVarianteService.crear({ productoId: formVar.productoId, ...datos });        avisar('Variante agregada');      }      cerrarFormVariante(); await recargar(); bus.emit('recargar');    } catch (e) { avisar(e.message, 'bad'); }  }  async function duplicarVariante(v) {    const p = productos.find(x => x.id === v.productoId);    if (!p) return;    prodSeleccionado = p;    mostrarFormVariante = true;    formVar = { editId: '', productoId: p.id, nombre: v.nombre + ' (copia)', codigo: '', unidad: v.unidad || '', precioBase: String(v.precioBase || ''), stockMin: String(v.stockMinimo || 5), esCaja: !!v.esCaja, unidadesPorCaja: String(v.unidadesPorCaja || ''), varianteUnidadId: v.varianteUnidadId || '', preciosEscalonados: clean(v.preciosEscalonados || []) };  }  async function archivarVariante(v) {    if (stockVariante(lotes, v.id) > 0) return avisar('No archivar con stock > 0', 'bad');    const ok = await confirmar('Archivar variante', 'Archivar ' + v.nombre + '?');    if (!ok) return;    await ProductoVarianteService.actualizar(v, { archivado: true });    await recargar(); bus.emit('recargar'); avisar('Variante archivada');  }  async function restaurarVariante(v) {    await ProductoVarianteService.actualizar(v, { archivado: false });    await recargar(); bus.emit('recargar'); avisar('Variante restaurada');  }  function fmtEscalones(pe) { if (!pe || pe.length === 0) return ''; return pe.map((e) => e.cantidadMinima + '+ @' + fmt(e.precioUnitario)).join(' | '); }  function clean(x) { if (x === null || typeof x !== 'object') return x; try { return structuredClone(x); } catch { return JSON.parse(JSON.stringify(x)); } }</script><div class='modulo'>  <!-- Form producto --><div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)] mb-3'>    <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>      <Icono nombre='tag' size={18} />      {formProd.editId ? 'Editar' : 'Agregar'} Producto Base    </div>    <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-2' type='text' placeholder='Nombre del producto (ej: Detergente Ariel)' bind:value={formProd.nombre} />    <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-3' type='text' placeholder='Codigo (opcional)' bind:value={formProd.codigo} />    <button class='w-full py-3 rounded-[var(--radius-md)] bg-primary text-white font-extrabold text-sm mb-2 active:scale-[0.97] transition-transform' onclick={guardarProducto}>      <Icono nombre='check' size={16} color='#fff' />      {formProd.editId ? 'Actualizar' : 'Guardar'} Producto    </button>    {#if formProd.editId}      <button class='w-full py-3 rounded-[var(--radius-md)] border border-border bg-transparent text-text font-extrabold text-sm active:scale-[0.97] transition-transform' onclick={resetFormProd}>Cancelar</button>    {/if}  </div>  <!-- Lista productos --><div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)]'>    <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>      <Icono nombre='tag' size={18} />      Productos    </div>    <div class='relative mb-3'>      <Icono nombre='search' size={16} class='absolute left-3 top-1/2 -translate-y-1/2 text-muted' />      <input class='w-full pl-9 pr-3.5 py-2.5 border border-border rounded-[var(--radius-md)] bg-card text-text text-sm outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='text' placeholder='Buscar...' bind:value={busq} />    </div>    <div class='text-right mb-3'>      <button class='inline-block px-3 py-1.5 rounded-[var(--radius-md)] border border-border bg-transparent text-text font-bold text-xs active:scale-[0.95] transition-transform' onclick={() => (mostrarArchivados = !mostrarArchivados)}>        {mostrarArchivados ? 'Ocultar archivados' : 'Ver archivados'}      </button>    </div>    {#if filtrados.length === 0}      <div class='text-center text-muted py-6 text-sm'>Sin productos</div>    {:else}      <div class='text-xs text-muted mb-2 px-1'>{filtrados.length} producto(s) · Pagina {pagina} de {totalPaginas}</div>      {#each filtradosPaginados as p}        {@const vars = variantesDeProducto(p.id)}        {@const varsArch = variantesArchivadas(p.id)}        <div class='mb-2'>          <div class='flex justify-between items-center gap-2 py-3 border-b border-border {p.archivado ? 'opacity-50' : ''}'>            <button class='flex-1 min-w-0 bg-transparent border-none text-left cursor-pointer' onclick={() => (expandido[p.id] = !expandido[p.id])}>              <div class='font-bold text-sm truncate'>                {p.nombre}                {#if p.codigo}<span class='text-muted font-normal text-xs'>({p.codigo})</span>{/if}              </div>              <div class='text-xs text-muted'>{vars.length} variante(s) activa(s)</div>            </button>            <div class='flex gap-1 flex-shrink-0'>              <button class='w-8 h-8 rounded-lg bg-background flex items-center justify-center border-none cursor-pointer active:scale-[0.92] transition-transform' onclick={() => editarProducto(p)}>                <Icono nombre='edit' size={15} />              </button>              {#if !p.archivado}                <button class='w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center border-none cursor-pointer active:scale-[0.92] transition-transform' onclick={() => abrirFormVariante(p)} title='Agregar variante'>                  <Icono nombre='plus' size={15} color='#2196f3' />                </button>                <button class='w-8 h-8 rounded-lg bg-danger/10 flex items-center justify-center border-none cursor-pointer active:scale-[0.92] transition-transform' onclick={() => archivarProducto(p)}>                  <Icono nombre='trash' size={15} color='#dc2626' />                </button>              {:else}                <button class='w-8 h-8 rounded-lg bg-success/10 flex items-center justify-center border-none cursor-pointer active:scale-[0.92] transition-transform' onclick={() => restaurarProducto(p)}>                  <Icono nombre='refresh' size={15} color='#16a34a' />                </button>              {/if}            </div>          </div>          {#if expandido[p.id]}            <div class='bg-background rounded-b-xl px-3 py-2'>              {#if vars.length === 0}                <div class='text-center text-muted text-xs py-2'>Sin variantes activas</div>              {:else}                {#each vars as v}                  {@const s = stockVariante(lotes, v.id)}                  {@const badge = badgeStockVariante(v, lotes)}                  <div class='flex justify-between items-center gap-2 py-2.5 px-3 bg-card rounded-lg mb-1.5 border border-border/30'>                    <div class='min-w-0 flex-1'>                      <div class='font-bold text-sm'>                        {v.nombre}                        {#if v.codigo}<span class='text-muted font-normal text-xs'>({v.codigo})</span>{/if}                        {#if v.esCaja}<span class='inline-block px-1.5 py-0.5 rounded text-[0.6rem] font-extrabold text-white bg-primary ml-1'>CAJA x{v.unidadesPorCaja}</span>{/if}                      </div>                      <div class='flex items-center gap-2 flex-wrap mt-1'>                        <span class='inline-block px-2 py-0.5 rounded-full text-[0.65rem] font-extrabold text-white {badge.clase === 'ok' ? 'bg-success' : badge.clase === 'low' ? 'bg-warning' : badge.clase === 'out' ? 'bg-danger' : 'bg-muted'}'>{badge.texto}</span>                        <span class='text-primary font-extrabold text-sm'>{fmtCant(s)} {v.unidad || ''}</span>                        <span class='text-muted text-xs'>{fmt(v.precioBase)}</span>                        {#if v.preciosEscalonados && v.preciosEscalonados.length > 0}                          <span class='text-xs text-success' title={fmtEscalones(v.preciosEscalonados)}>Escalones</span>                        {/if}                      </div>                    </div>                    <div class='flex gap-1 flex-shrink-0'>                      <button class='w-7 h-7 rounded-lg bg-background flex items-center justify-center border-none cursor-pointer active:scale-[0.92] transition-transform' onclick={() => abrirFormVariante(p, v)}>                        <Icono nombre='edit' size={13} />                      </button>                      <button class='w-7 h-7 rounded-lg bg-primary/10 flex items-center justify-center border-none cursor-pointer active:scale-[0.92] transition-transform' onclick={() => duplicarVariante(v)} title='Duplicar variante'>                        <Icono nombre='copy' size={13} color='#2196f3' />                      </button>                      <button class='w-7 h-7 rounded-lg bg-danger/10 flex items-center justify-center border-none cursor-pointer active:scale-[0.92] transition-transform' onclick={() => archivarVariante(v)}>                        <Icono nombre='trash' size={13} color='#dc2626' />                      </button>                    </div>                  </div>                {/each}              {/if}              {#if varsArch.length > 0}                <div class='text-xs text-muted mt-2 px-1'>{varsArch.length} variante(s) archivada(s)</div>                {#each varsArch as v}                  <div class='flex justify-between items-center gap-2 py-1.5 px-2 opacity-50'>                    <span class='text-sm'>{v.nombre} <span class='text-muted text-xs'>(archivada)</span></span>                    <button class='w-7 h-7 rounded-lg bg-success/10 flex items-center justify-center border-none cursor-pointer active:scale-[0.92] transition-transform' onclick={() => restaurarVariante(v)}>                      <Icono nombre='refresh' size={13} color='#16a34a' />                    </button>                  </div>                {/each}              {/if}            </div>          {/if}        </div>      {/each}      {#if totalPaginas > 1}        <div class='flex items-center justify-center gap-2 mt-4'>          <button class='w-10 h-10 rounded-lg bg-background border border-border flex items-center justify-center disabled:opacity-30 active:scale-[0.92] transition-transform' onclick={() => (pagina = Math.max(1, pagina - 1))} disabled={pagina === 1}>            <Icono nombre='chevron' size={16} class='rotate-90' />          </button>          <span class='text-xs text-muted font-bold px-2'>{pagina} / {totalPaginas}</span>          <button class='w-10 h-10 rounded-lg bg-background border border-border flex items-center justify-center disabled:opacity-30 active:scale-[0.92] transition-transform' onclick={() => (pagina = Math.min(totalPaginas, pagina + 1))} disabled={pagina === totalPaginas}>            <Icono nombre='chevron' size={16} class='-rotate-90' />          </button>        </div>      {/if}    {/if}  </div>  <!-- Modal variante -->{#if mostrarFormVariante && prodSeleccionado}<div class='fixed inset-0 bg-black/50 z-[100] flex items-center justify-center p-4 no-print' role='dialog' aria-modal='true'>    <button class='absolute inset-0 w-full h-full bg-transparent border-none cursor-default' onclick={cerrarFormVariante}></button>    <div class='bg-card rounded-[var(--radius-lg)] p-5 w-full max-w-md shadow-[0_10px_40px_rgba(0,0,0,0.3)] animate-pop relative z-10 max-h-[90vh] overflow-y-auto'>      <div class='flex items-center gap-2 font-extrabold text-primary text-lg mb-2'>        <Icono nombre='tag' size={20} />        {formVar.editId ? 'Editar' : 'Nueva'} Variante      </div>      <div class='text-xs text-muted mb-3'>Producto: <b class='text-primary'>{prodSeleccionado.nombre}</b></div>      <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-2' type='text' placeholder='Nombre de variante (ej: 1kg, Caja x12)' bind:value={formVar.nombre} />      <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-2' type='text' placeholder='Codigo SKU (opcional)' bind:value={formVar.codigo} />      <div class='grid grid-cols-2 gap-2 mb-2'>        <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='number' inputmode='decimal' step='0.01' placeholder='Precio base' bind:value={formVar.precioBase} />        <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' type='number' inputmode='decimal' step='0.1' placeholder='Stock min.' bind:value={formVar.stockMin} />      </div>      <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-2' type='text' placeholder='Unidad (kg, gr, litro, u, caja)' bind:value={formVar.unidad} list='unidades-list' />      <datalist id='unidades-list'><option value='u'></option><option value='kg'></option><option value='lb'></option><option value='gr'></option><option value='litro'></option><option value='m'></option><option value='caja'></option><option value='paq'></option></datalist>      <div class='bg-background rounded-lg p-3 mb-2'>        <label class='flex items-center gap-2 cursor-pointer mb-2'>          <input type='checkbox' bind:checked={formVar.esCaja} class='w-5 h-5 accent-primary' />          <span class='text-sm font-bold'>Es presentacion por caja</span>        </label>        {#if formVar.esCaja}          <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-2' type='number' inputmode='decimal' placeholder='Unidades que trae la caja' bind:value={formVar.unidadesPorCaja} />          <select class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)]' bind:value={formVar.varianteUnidadId}>            <option value=''>Variante unidad suelta relacionada...</option>            {#each variantes.filter(v => v.productoId === prodSeleccionado.id && v.id !== formVar.editId && !v.esCaja && !v.archivado) as v}              <option value={v.id}>{v.nombre} ({v.unidad})</option>            {/each}          </select>        {/if}      </div>      <div class='bg-background rounded-lg p-3 mb-2'>        <div class='flex justify-between items-center mb-2'>          <span class='text-sm font-bold'>Precios por volumen</span>          <button class='text-xs bg-primary text-white px-2 py-1 rounded font-bold border-none cursor-pointer active:scale-[0.95] transition-transform' onclick={agregarEscalon}>+ Agregar</button>        </div>        {#if formVar.preciosEscalonados.length === 0}          <div class='text-xs text-muted'>Sin precios escalonados</div>        {:else}          {#each formVar.preciosEscalonados as pe, i}            <div class='flex items-center gap-2 mb-2'>              <input class='flex-1 px-3 py-2 border border-border rounded-[var(--radius-md)] bg-card text-text text-sm outline-none' type='number' inputmode='decimal' placeholder='Cant. minima' bind:value={pe.cantidadMinima} />              <span class='text-muted text-xs'>@</span>              <input class='flex-1 px-3 py-2 border border-border rounded-[var(--radius-md)] bg-card text-text text-sm outline-none' type='number' inputmode='decimal' step='0.01' placeholder='Precio unit.' bind:value={pe.precioUnitario} />              <button class='w-8 h-8 rounded-lg bg-danger/10 flex items-center justify-center border-none cursor-pointer active:scale-[0.92] transition-transform' onclick={() => quitarEscalon(i)}>                <Icono nombre='x' size={14} color='#dc2626' />              </button>            </div>          {/each}        {/if}      </div>      <button class='w-full py-3 rounded-[var(--radius-md)] bg-primary text-white font-extrabold text-sm mb-2 active:scale-[0.97] transition-transform' onclick={guardarVariante}>        <Icono nombre='check' size={16} color='#fff' />        {formVar.editId ? 'Actualizar' : 'Guardar'} Variante      </button>      <button class='w-full py-3 rounded-[var(--radius-md)] border border-border bg-transparent text-text font-extrabold text-sm active:scale-[0.97] transition-transform' onclick={cerrarFormVariante}>Cancelar</button>    </div>  </div>{/if}</div>